package com.reevil.client.ndesu;

import com.reevil.ReEvilMod;
import com.reevil.client.mrx.MrXModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.resources.ResourceLocation;

/** Own silhouette (generated by tools/variantgen.py): the MrXModel rig, so all clips apply, with replaced/added parts. */
public class NdesuModel extends MrXModel {
    public static final ModelLayerLocation LAYER = new ModelLayerLocation(new ResourceLocation(ReEvilMod.MODID, "ndesu"), "main");
    public NdesuModel(ModelPart root) { super(root); }
    public static LayerDefinition createBodyLayer() {
        MeshDefinition mesh = MrXModel.mesh();
        PartDefinition root = mesh.getRoot();
        root.getChild("base").getChild("torso").addOrReplaceChild("spikes", CubeListBuilder.create()
            .texOffs(0, 64).addBox(-7.5f, -12, -1, 3, 3, 3)
            .texOffs(12, 64).addBox(4.5f, -12, -1, 3, 3, 3)
            .texOffs(24, 64).addBox(-1, -12, 2.5f, 2, 6, 2)
            .texOffs(32, 64).addBox(-4, -9, 2.5f, 2, 5, 2)
            .texOffs(40, 64).addBox(2, -9, 2.5f, 2, 5, 2),
            PartPose.ZERO);
        root.getChild("base").addOrReplaceChild("loin", CubeListBuilder.create()
            .texOffs(48, 64).addBox(-5, 0, -3, 10, 7, 1)
            .texOffs(70, 64).addBox(-5, 0, 2, 10, 7, 1),
            PartPose.ZERO);
        root.getChild("base").getChild("torso").getChild("armR").getChild("foreR").getChild("handR").addOrReplaceChild("mace", CubeListBuilder.create()
            .texOffs(92, 64).addBox(-0.6f, -2, -0.6f, 1.2f, 18, 1.2f)
            .texOffs(100, 64).addBox(-3, 14, -3, 6, 7, 6)
            .texOffs(0, 84).addBox(-0.5f, 12, -4.5f, 1, 1, 9),
            PartPose.offsetAndRotation(0, 2, -1, -0.5f, 0, 0));
        return LayerDefinition.create(mesh, 128, 96);
    }
}
